from playwright.sync_api import sync_playwright
import json, re

def scrape_neurips():
    all_papers = []

    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()

        # 1. Get POSTER papers
        print("Scraping poster papers...")
        page.goto("https://neurips.cc/virtual/2024/papers.html?filter=titles", wait_until="domcontentloaded", timeout=60000)
        page.wait_for_timeout(8000)

        poster_data = page.evaluate("""() => {
            const cards = document.querySelectorAll(".myCard");
            return Array.from(cards).map(c => {
                const html = c.innerHTML;
                const titleMatch = html.match(/card-title">\\s*([^<]+)/);
                const title = titleMatch ? titleMatch[1].trim() : null;
                const hrefMatch = html.match(/href="([^"]*\\/\\d+)"/);
                const paper_id = hrefMatch ? hrefMatch[1].split("/").pop() : null;
                const authorAnchors = c.querySelectorAll("h6.card-subtitle a");
                const first_author = authorAnchors.length ? authorAnchors[0].innerText.trim() : null;
                return {title, paper_id, first_author, type: "poster"};
            });
        }""")
        print(f"  Found {len(poster_data)} poster papers")
        all_papers.extend(poster_data)

        # 2. Get ORAL papers
        print("Scraping oral papers...")
        page2 = browser.new_page()
        page2.goto("https://neurips.cc/virtual/2024/events/oral", wait_until="domcontentloaded", timeout=60000)
        page2.wait_for_timeout(8000)

        oral_data = page2.evaluate("""() => {
            const cards = document.querySelectorAll(".myCard");
            return Array.from(cards).map(c => {
                const html = c.innerHTML;
                const titleMatch = html.match(/card-title">\\s*([^<]+)/);
                const title = titleMatch ? titleMatch[1].trim() : null;
                const hrefMatch = html.match(/href="([^"]*\\/\\d+)"/);
                const paper_id = hrefMatch ? hrefMatch[1].split("/").pop() : null;
                const authorAnchors = c.querySelectorAll("h6.card-subtitle a");
                const first_author = authorAnchors.length ? authorAnchors[0].innerText.trim() : null;
                return {title, paper_id, first_author, type: "oral"};
            });
        }""")
        print(f"  Found {len(oral_data)} oral papers")
        all_papers.extend(oral_data)

        # 3. Get SPOTLIGHT papers
        print("Scraping spotlight papers...")
        page3 = browser.new_page()
        page3.goto("https://neurips.cc/virtual/2024/events/spotlight-posters-2024", wait_until="domcontentloaded", timeout=60000)
        page3.wait_for_timeout(8000)

        spotlight_data = page3.evaluate("""() => {
            const cards = document.querySelectorAll(".myCard");
            return Array.from(cards).map(c => {
                const html = c.innerHTML;
                const titleMatch = html.match(/card-title">\\s*([^<]+)/);
                const title = titleMatch ? titleMatch[1].trim() : null;
                const hrefMatch = html.match(/href="([^"]*\\/\\d+)"/);
                const paper_id = hrefMatch ? hrefMatch[1].split("/").pop() : null;
                const authorAnchors = c.querySelectorAll("h6.card-subtitle a");
                const first_author = authorAnchors.length ? authorAnchors[0].innerText.trim() : null;
                return {title, paper_id, first_author, type: "spotlight"};
            });
        }""")
        print(f"  Found {len(spotlight_data)} spotlight papers")
        all_papers.extend(spotlight_data)

        browser.close()

    print(f"\nTotal NeurIPS 2024 papers: {len(all_papers)}")
    print(f"  Oral: {len([p for p in all_papers if p['type']=='oral'])}")
    print(f"  Spotlight: {len([p for p in all_papers if p['type']=='spotlight'])}")
    print(f"  Poster: {len([p for p in all_papers if p['type']=='poster'])}")

    with open("/app/neurips_2024.json", "w") as f:
        json.dump(all_papers, f)

    return all_papers

